mapper.select:
SELECT p.*, (SELECT COUNT(*) FROM device d WHERE d.plot_id = p.id AND d.deleted = 0) as deviceCount, (SELECT COUNT(*) FROM device d WHERE d.plot_id = p.id AND d.online_status = 1 AND d.deleted = 0) as onlineDeviceCount FROM plot p WHERE p.deleted = 0
AND p.plot_code LIKE CONCAT('%', #{dto.plotCode}, '%')
AND p.plot_name LIKE CONCAT('%', #{dto.plotName}, '%')
AND p.crop_type = #{dto.cropType}
AND p.status = #{dto.status}
ORDER BY p.create_time DESC
